INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437692-mgt301', 'stk-practice', 'MGT 301', 'info', '{"desc": "اخذتها مع الدكتور سالم الغامدي بترم 151\n\nالمادة تتكلم عن تصنيف الموظفين في الشركة - كيف تتحدى شركات ثانية وتفوز - كيف تنمدج شركتين مع بعض - التحفيز - القيادة - التواصل - التحكم - التغير\n\nكلامها مفهوم … ما كنت افتح الكتاب ابدا ، الدكتور كان يخلينا نكتب معاه نوت\n\nموفقين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-301-principles-of-management/120989/9", "user": "Practice", "ts": 1451687250000, "tid": 120989, "pn": 9}}', 1451687250000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1440978-mgt301', 'stk-user10207', 'MGT 301', 'info', '{"desc": "انت شوف اول الكويزات او الميجر\nاذا كان يحتاج مذاكرة من الكتاب ولا السلايدات.\n\nاذا السلايدات كويسة، ذاكر منها. والكتاب حدد الاشياء\nالمهمة مثل التعاريف.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-301-principles-of-management/120989/11", "user": "user10207", "ts": 1454199091000, "tid": 120989, "pn": 11}}', 1454199091000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1448989-mgt301', 'stk-user8581', 'MGT 301', 'info', '{"desc": "كورس غثيث وفيه حفظ كثير وراح تتعب خاصة إذا كان دكتورك يعتمد على الكتاب في وضع الأسئلة ومايعتمد على tb\nأستغرب ليش الكورس مطلوب من بعض التخصصات الهندسية والحاسب !\nانا خذته مع RAZALI BIN MAT ZIN هو حبيب ومتعاون لكن اسئلته اشوفها صعبة إن شاء الله راح ارفع ملفات للكورس بعد الفاينلات .\nد.المير على حسب كلام الشباب حليو واسئلته من الـ tb لكن يعدل عليها بشكل بسيط …\nما بعد يعطينا القريد لكن طلعت المادة عكس الي كنت متوقعه … كنت افكره كورس خفيف وسهالات وطلع كله حفظ وهذرة مالها داعي ولا فايدة .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-301-principles-of-management/120989/14", "user": "user8581", "ts": 1463256655000, "tid": 120989, "pn": 14}}', 1463256655000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1475979-mgt301', 'stk-user9840', 'MGT 301', 'info', '{"desc": "كورس غثيث جدا وفيه كمية حفظ غير طبيعية خصوصا اذا كنت منزله مع رزالي ، يبيك تذاكر الكتاب من الجلده للجلده . هالكورس يعتمد على الدكتور فمثلا لو كان هالكورس مع ماكسويل راح يفرق كثير . كرهت كورسات المنجمنت بسبب رزالي ، لكن هو بحد ذاته الكورس مثل ما قلت لكم سهل لو كان مع دكتور جيد .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-301-principles-of-management/120989/19", "user": "user9840", "ts": 1499307148000, "tid": 120989, "pn": 19}}', 1499307148000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1509715-mgt301', 'stk-_182', 'MGT 301', 'info', '{"desc": "- المادة تحوي معلومات كثيرة، تعريفات عديدة وتقسيمات كثيرة كذلك، طبعًا كغيرها من مواد الإدارة، فيه كثير من التعريفات بديهيّة\n- المادة مو صعبة أبدًا، ولكن مثل ما ذكرت فيه كم لا بأس به من المعلومات، وكل اختبار يغطي 4 إلى 6 فصول\n- صعوبة الاختبار من عدمها تعتمد على مدرس المادة، بما أن الاختبارات مو موحدة، فبعض الدكاترة يخلي اختباره خيارات، والبعض خيارات ومقالي، فكل دكتور وطريقته.\n- الكتاب ممتاز، محتواه واضح وموجز (ما فيه تمطيط بالكلام)\n- المادة مفيدة، وإذا حصل لك فرصة تاخذها مع د. عيد الشمري فتوكّل\n\nالفصول التي غُطّيت خلال الترم (تشابتر 12 محذوف)\nCh 01 Introduction to Management & Organizations\nCh 02 Management History\nCh 03 Organizational Culture & Environment\nCh 04 Managing in a Global Environment\nCh 05 Social Responsibility & Managerial Ethics\nCh 06 Managers as Decision Makers\nCh 07 Foundations of Planning\nCh 08 Strategic Management\nCh 09 Organizational Structure & Design\nCh 10 Managing Human Resources\nCh 11 Managing Teams\nCh 13 Understanding Individual Behavior\nCh 14 Managers & Communication\nCh 15 Motivating Employees\nCh 16 Managers as Leaders", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-301-principles-of-management/120989/24", "user": "_182", "ts": 1557840177000, "tid": 120989, "pn": 24}}', 1557840177000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p25430-mgt301', 'stk-user245', 'MGT 301', 'info', '{"desc": "طيب\n\nالمادة التي ذكر ت إدارة 301 ( معتمده علىالحفظ ) …!!\nإذا تبي مادة سهله تجمع بين الحفظ البسيط + العمل الخفيف + فهم على خفيف\nو الكريد يكون طيب و تعامل المدرس فله …!!!\nفالنصيحه لك من أكثر من أخ سألتهم يقولون ::: مادة إدارة 420 عند ابو بشيت\n\nلكن عليك بالتالي ::\nلا تغيب البته\nخلك متفاعل مع المدرس ( يعني يصير يعرفك بأسمك )\nكن طالب مطيع و مجتهد\n-------------------------------\nطريقة المدرس في المادة يقال ::\nكل مجموعة تلخص فصل من الكتاب و يقدمون شرح لمدة 10 دقائق امام الطلاب\nكل مجموعة تسوي بحث ( تدرس أي شركة بموضوع الكتاب …) سهل مره .\nما فيه كوزات\nفقط ( إختبار نصفي و نهائي )\nو الدرجات في النهاية على حسب درجاتك + شخصيتك في مخ المدرس :: يعني يمكن أنك تستاهل فقط +C و يعطيك +B عشانك طالب ما تغيب و مؤدب و متفاعل …!!\n\nهذا و الله أغلم و العهده على الشباب الذين درسوا عنده و هم ثلاثة ::\nواحد أخذ +B والثاني A و الثالث B\n---------------------------------------------\n\n&& خفاش &&", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt301/22774/5", "user": "user245", "ts": 1056852097000, "tid": 22774, "pn": 5}}', 1056852097000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p114865-mgt301', 'stk-final', 'MGT 301', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nحاب اسألكم اخواني الاداريين بخصوص هؤلاء الدكاترة لمادة mgt301\nمن هو الافضل بنظرك\n\nAZHAR K\n\nاو\n\nACHOUI M\n\nوكيف طريقة كل واحد منهما في تدريس الماده + توزيع القريد\n\nوايهما اختباراته من ال TB @4@\n\nوهل المادة فيها بروجيكت@3@\n\nوسلامتكم\n\nمشكورين مسبقاً\n\nاخوكم @37@ final", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/com/52007/1", "user": "final", "ts": 1157533156000, "tid": 52007, "pn": 1}}', 1157533156000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p857213-mgt301', 'stk-fond_of_you', 'MGT 301', 'info', '{"desc": "انا نزلت نفس هالمواد بالسمستر 101 … وماكنت بالصعوبة اللي انت مصورها …\n\nانا خذت ال325 و323 و303 و361 و mgt 301\n\nال361 مادة يبغى لها شغل بس ترمه خفيف لازم يوازن …\n\nوالمادة ما دمرت المعدل ولا شيء بس يبغى لها حفظ يعني يومين قبل الميجر تكفي …\n\nانا بالنسبة لي كنت ساحب عليها ما اعطيتها حقها يعني يوم او يوم ونص بالكثير قبل الميجر …\n\nودرجاتي فوق الافرج بشوي بس يعني يمكن درجة و الفاينل فوق الافرج ب3 درجات…\n\nوعطاني بي يعني لا دمر المعدل ولا شيء 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ise-103-111/106128/264", "user": "Fond_Of_You", "ts": 1308694113000, "tid": 106128, "pn": 264}}', 1308694113000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p418390-mgt301', 'stk-mis_action', 'MGT 301', 'info', '{"desc": "شوف … طبعا ً هذا شيء محزن ومثير للشفقة … سالفة الكوبي بيست هذي … وأنا ذكرت الكلام هذا بخصوص ال MGT 301 …\nوتفاجت صراحة بال MIS … لكن ليش لأ … الدنيا تتغير !!\n\nأخ كفبوم …بجيك ألحين بس ثواني.\n\nبالنسبة للمتهندسين … هذا واحد منكم وفيكم مهندس شوفوا وش يقول. 😆\n\nميجر … نصا من الهومورك ؟ 😍 …\nيخوي أنا إداري …بالنهاية راح أعتمد على خبراتي الإجتماعية … لكن إنت مهندس\n\nوهذا نفس الطالب … عينة من طلاب الهندسة … شوفوا\n\n… و كل سمستر يعيد الاختبار … يعني يغير التاريخ و رقم السمستر في غلاف الاختبار و يعطيك الاختبار … مثلا ميجر ون لما اخذت عنده كان … بالضبط نصا لميجر ون للسمسترين اللي سبقوا السمستر اللي كنا فيه … اللهم السؤال الاخير حذفه (لانه كان شوي صعب)و استبدله بسؤال تعريفات SIGNAL,SYSTEM سؤال بسيط يعني هدية\nالدرجات النهائية … حلوة …\n\n👍 يا عيني يا هندسة … !!!\nأنا ودي هذاك الي جالس يتفلسف ويقول عن طلاب الإدارة ( يفوقوا من سباتهم ) 😏 … يجي يقرا كلام أخوه المهندس… وخلينا نشوف من الي يفوق من سباته ؟!!\nياشيخ ما غير أقومك من النوم بسلك 400 فولت … 😆 …\n\nطلاب الإدارة ليس لهم ذنب بال تي بي إلي مو عاجبكم… وكأنهم مسؤولين عن ال TB\nلازم الدكتور الشمري يدخل مثل ما قال أخوي كفبوم … إذا الموضوع زاد وتفاقم عن حده.\nأخوي كفبوم … إذا أنت فعلا ً متضرر … اطبع الموضوع هذا … وأجمع أكبر عدد ممكن من مشاركات طلاب الإدارة إلي مستاءة من ال TB … وسلمها للشمري … مو عشان توصله المعلومة …لا …بس عشان تقيم عليه الحجة, لأني متأكد إنه يدري. وإذا ما يدري … والوضع متفاقم إلى هذي الدرجة … فهذي مصيبة أعظم\n\nنراكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/74216/52", "user": "MIS_Action", "ts": 1245739043000, "tid": 74216, "pn": 52}}', 1245739043000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1122108-mgt301', 'stk-user5937', 'MGT 301', 'info', '{"desc": "FIN Analyst\n\nالستات 212 بنزلها بالصيف ان شاء الله … ابي الربوع اوف 🤠\n\nبالنسبة لــ om … وش طبيعة الماده وهل تحتاج فهم مثل الستات والاكاونتنق … أسهل هي ولا mgt 301 … الأسهل بنزله لأن مثل ما انت شايف 5 مواد بدون عربي او اسلامي او بي 😐 فأحسها صعبه نوعا ما\n\nومشكور على تفاعلك 🌺\n\nĄЪŐ…Şαļļў\n\nالتفكير جاري في الــ om\n\nالف شكر 🌺", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/135123/6", "user": "user5937", "ts": 1353674409000, "tid": 135123, "pn": 6}}', 1353674409000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p628906-mgt301', 'stk-ahmed-linux', 'MGT 301', 'srcP', '{"html": "السلام عليكم ورحمة الله وبركاته<br><br>قمت برفع سيرة ذاتية لحياة شخصين ناجحين الأولى عربية وهو الدكتور محمد البرادعي والآخر هو محرر جنوب أفريقيا من الرق الأوروبي نيلسون مانديلا أرجو أن تحوز على إعجابكم.<br><br>-----------------------------------------<br><br>​<span data-fid=\"stk-f628906-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f628906-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f628906-0": {"name": "mgt301 assignment (bradie’s_biography).pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/ccfc16c3642551745f20efe63172287d009bb249245d4a48fa2b2a2e06d43606"}, "stk-f628906-1": {"name": "mgt301 assginment (nilson’s_biography).pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/d31c0276101601ddc7ece4726991b4a9039f5545f0087356e66b2b23fd787224"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/89782/1", "user": "Ahmed-Linux", "ts": 1276303624000, "tid": 89782, "pn": 1}}', 1276303624000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-practice-mgt301', 'stk-practice', 'MGT 301', 'doc', '{"docs": [{"id": "stk-dr-f98447", "n": "Dr. Salem M. Al-Ghamdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معه Mgt301 جابوه لنا بدال الاستاذ عبد المحسن\n\nالدكتور هذا جدا جدا جدا بطل !!\n\nانا ما اطيق الدوام من يومي لكن مع الدكتور ذا تتحمس وانت رايح كلاسه\n\nكلاسه ممتع جدا ويفيدك كثييير من الجانب الوظيفي بعد\n\nيطلب انك تكتب معاه وهو يشرح والميجر والفاينل من الكلام ذا ما يحتاج تفتح لا تي بي ولا كتاب ولا سلايدات … والكلام اللي كاتبه ما يتعدا 20 صفحة وبخط يدك يعني قدك عارفه\n\nالميجر والفاينل كله ريتن عبارة عن 4 او 5 اسئلة حل كل واحد منها 4 - 5 سطور بالكثير … يمديك تجيب فل مارك بسهولة معاه\n\nعنده بروجكت غثيث شوي … synthsis بمعنى انك تدور 8 مقالات انت وخويك عن موضوع معين لكن بشرط يكون فيه توافق واختلاف بين ذي المقالات ( ياخذ وقت كبير ابال ما تلاقي مقالات متفقة على نفس الكلام او مختلفة ) وتسوي برزنتيشن عليه بسلايدات او بدون ويسالك اذا كان فيه توافق بين الارتلكز حقتك واللي درسته في الكلاس … 10 Minutes maximum\n\nما ادري عن الفاينل قريد لكن انصح فيه من ناحية الراحة والشرح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1436582-mgt301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-salem-m-al-ghamdi/98447/8", "user": "Practice", "ts": 1450779173000, "tid": 98447, "pn": 8}}, {"id": "stk-dr-f172579", "n": "Dr. Abdulmohsen A. Alghamdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT301 - 151\n\nدرسني اول شهر بعدين اعتذر وجا بداله الدكتور سالم الغامدي وقميته بموضوعه ، بالنسبة للاستاذ عبد المحسن\n\n1- كويزاته كل اسبوعين كانت ومن التست بانك + من شرحه الجانبي اللي ماله علاقة بالكورس ، مثال : Six Sigma\n2- شرحه قراية من السلايدات مع مناقشة بسيطة\n3-يقدس اللي ما يغيب ولا غياب ويهتم كثير بالتحضير وقال لنا اللي يجي اول كلاس بالمادة له بونس واللي ماله ولا غياب وعد مني A+ هذا كلامه\n4- حبوب وما تشيل هم كلاسه وغير كذا شبابي\n5- اختبرت معاه ميجر ون وكان تست بانك + اسئلة مقالية عادة من شرحه والحاجات اللي حددها قبل الميجر\n\nانا زعلت لما تغير وجا بداله دكتور ثاني ، لكن الصدق الدكتور سالم الغامدي اللي جانا كان افضل منه من ناحية الشرح وجو الكلاس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1458997-mgt301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-abdulmohsen-a-alghamdi/172579/4", "user": "Practice", "ts": 1475062459000, "tid": 172579, "pn": 4}}]}', 1450779173000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10140-mgt301', 'stk-user10140', 'MGT 301', 'doc', '{"docs": [{"id": "stk-dr-f98453", "n": "Dr. Sammer Hammad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سامر حماد من طلاب الجامعة القدامى، جاء كمدرس مساعد لمادة mgt301 لفترة 5 أسابيع بعدها استلم الدكتور رزالي المادة. يقولون انه السمستر الجاي راح يسوي نفس الشيء.\n\nالكويزات المياجر كلها بيد الرزالي لذلك ما لها تقييم. شرح الدكتور جيد، ما راح يفيدك في الإختبار أبداً، لكنه يعطيك معلومات عامة عن الإدارة و عن تجاربه مع الوزارات و الشركات هنا. حضورك مطلوب للكلاس لكنه يسوي بث مباشر على صفحته في الفيسبوك، يعني لو غبت ما يفوتك شيء. و ألغى واحد من الكلاسات و طلب منا نحضر جلسة مع التاجر صلاح الشيخ، مالك و مدير المتجر الوطني. يقول ان السمستر الجاي راح يسوي أكثر من جلسة بهالطريقة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1471720-mgt301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-sammer-hammad/98453/4", "user": "user10140", "ts": 1492761346000, "tid": 98453, "pn": 4}}]}', 1492761346000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kbsc-mgt301', 'stk-kbsc', 'MGT 301', 'doc', '{"docs": [{"id": "stk-dr-f98453", "n": "Dr. Sammer Hammad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور :\n\nسامر حمّاد\n\nالمادة:\n\nMGT 301\n\nطريقة الشرح :\n\nتجارب حياة + سلايدات + Guest Speaker\n\nالكويزات :\n\nدكتور رزالي كان ماسك المادة و كويزاته من متوسط إلى صعب من السلايدات عن فهم و ليس حفظ\n\nالمياجر/ميد:\n\nليس TB ، بالعكس مثل الكويزات تعتمد على فهمك للمادة و ليس حفظها\n\nالفاينل :\n\nلسى ما اختبرنا بس الله العالم نفس نظام الكويزات و المياجر.\n\nطريقة التحضير :\n\nتوقيع\n\nالقريد النهائي الخاص بك :\n\nإحتمال B or B+\nاضافات:\n\nالدكتورين أسطوريين ، قصص مفيدة و ثريّة بالمعلومات و التجارب ، الدكتورين حبيبين و يقدّرون الطالب و متعاونين لأبعد حد ، تجربة مفيدة جدّاً و كمان إذا الطالب مجتهد بيحصّل على القريد اللي يبيه ، و كل طالب و اجتهاده ، و لكن إذا الطالب كان مهتم للقريد و الفائدة فهذا المكان المناسب ، طلاب المانجمنت خاصّةً لا يفوتكم أي واحد من هذين الدكتورين و لكن إذا فيه سكشن ماسكه دكتور سامر حمّاد لحاله و سكشن ماسكه رزالي لحاله يفضّل تروح مع سكشن دكتور سامر ، لأنه أفضل من رزالي مع العلم إن رزالي كويس عكس الكلام الموجود في المنتدى .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507359-mgt301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-sammer-hammad/98453/5", "user": "KBSC", "ts": 1552816738000, "tid": 98453, "pn": 5}}]}', 1552816738000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-mgt301', 'stk-guest', 'MGT 301', 'doc', '{"docs": [{"id": "stk-dr-f98453", "n": "Dr. Sammer Hammad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "٢٠١ - اونلاين - MGT 301\nنصيحة لحد ينخدع بالكلام المكتوب عن الدكتور\nبأختصار نظام الدكتور كالتالي: تحضر معاه المحاضرة اللي نصها تحضير للطلاب ومافيها شرح لأي شيء ويطلب منك تشاهد محاضراته باليوتيوب يعني راح تضيع وقتك … كل كلاس فيه كويز قصير (غالبا سهل جدًا بس انه بكل كلاس)\nالدكتور ماعنده نظام لا في تنزيل الدرجات اول بأول ولا في السيلابز ف تلاقي كل الطلاب ضايعين\nالقروب بروجكت ماتدري هو ايش يبغا او كيف راح يقيم، يحطك بمجموعة وفجأة بنص السمستر يقول انتو مهملين ويحدد الduo time بعشوائية ( بالترم اللي عندي ماشرح لنا طريقة الريبورت ولا اي شيء وفجأه قبل اسبوعين من الترم فصل علينا قال انتو مهملين محد سلم لي البروجكت؟؟؟؟ )\nبالنهاية الدرجات يقيمك بعشوائية، انا سويت كل المطلوب واعطاني ٨ من ١٠ بكل الريبورتات حق القست سبيكر ( حرفيا ولا واحد عطاني فيه درجة كاملة ) وخسرت ٤ درجات يعني قريد كامل بدون سبب\nونفس الشيء بالقروب بروجكت م تدري على اي اساس يحسب الدرجة! وكمان في السمستر يتفاخر انه م يعطي احد A+\nالدكتور مستفز جدًا جدًا لا اسلوب في التدريس ولا شرح يستاهل تنزل عنده!!!\n\nلاتتوقع انه يدفك بالنهاية لو جبت كويس بالفاينل … انا كنت راح احذف المادة لان الافرج بالمدترم كان مرة سيئ ف كلمته وقالي جيب كويس بالفاينل وان شاء الله خير … ما اعطاني ولا درجة وفوق هذا نقصني بطريقة مستفزة بباقي الاعمال\nوفي طلاب جابو معه F مدري مشاهم بالاخير او لا …\n\nنزل عنده فقط اذا كان الخيار الوحيد عندك والله يعينك عليه!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527689-mgt301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-sammer-hammad/98453/6", "user": "Guest", "ts": 1610070247000, "tid": 98453, "pn": 6}}]}', 1610070247000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-imported83-mgt301', 'stk-imported83', 'MGT 301', 'doc', '{"docs": [{"id": "stk-dr-f98458", "n": "Dr. Abdulwahab S. Al-Gahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا أخذت معاه mgt 301 بالصيف الماضي 093\n\nشرحه جدا ممتع و مثقف و مطلع على كثير من الأمور\nو يراعي ثقافة الطالب بإعطائه أمثلة حسب اهتماماته و يقرب له الصورة\nو لا تشعر بالممل, لأنه يخرج من الشرح و يتحدث عن المشاكل الإدارية في واقعنا\nالدكتور ما شاء الله عليه, لديه خبرة واسعة في مجاله\n\nبتركيز معاه بالكلاس تطلع فاهم الموضوع, و أكيد بقراءة الكتاب للترسيخ أكبر\n\nيهتم بشكل كبير بموضوع الغياب, لذلك احرص على عدم الغياب أبدا\nو فيه بونس للي ما عندهم غياب\nعطانا ثلاث واجبات نلخص المواضيع اللي يوزعها لنا من إحدى الكتب, و أحدهم من مقاله في إحدى الجرايد\n\nبالنسبة للمياجر\nميجرين و فاينل\n25\n25\n25\n\nالأسئلة واضحة و أكثرها مباشرة و يعتمد على فهم المادة\nذاكر من الكتاب و الكتاب ممتع و بها كثير من الأمثلة الحلوة\n\nهذا بالنسبة لـ mgt 301 بالصيف\nأما باقي المواد و خلال الترم, ما أدري إذا أسلوبه متغير أو لا\n\nتحياتي لكم\n🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p856940-mgt301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulwahab-s-al-gahtani/98458/10", "user": "imported83", "ts": 1308658603000, "tid": 98458, "pn": 10}}]}', 1308658603000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-i_bo_da7m-mgt301', 'stk-i_bo_da7m', 'MGT 301', 'doc', '{"docs": [{"id": "stk-dr-f98462", "n": "Dr. Abdulrahim A. Al-Meer", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الله يسامح أعضاء قسم تخصصكم ( تخصص الإدارة ) اللي درسوا عنده\nوماعطونا معلومات عنه 😭\n\n>> أنـا تخصصي هندسة ميكانيكية , وأمشي على الخطة القديمة ,\nومو مطلوب منّي أنزلها أبداً , ولا حتى إليكتيف ,\n\nلكن انا على مشارف التخرج < والمعدل يبغى له رفع شوي للتخرج , وسلامة فهمكم 🙂\n\nنصحوني اخوياي طلاب إليكتريك بتنزيل هالمادة , وقالوا لي إنها تيست - بنك … يعني احفظ الإختيارات وبيجيك مثلها , هذا نظام المادة , وطلع للأسف إنها مادة حفففففففففففففففظ\nوأنا بطل بالفهم , سيء بالحفظ 😦 , ولا قدرت احذفها بعد الحذف لأني منزل 12 ساعه\n\nنجي للدكتور المير الله يسامحه , ويبعد امثاله من هالجامعه 😞\n^\nالترم :\n121\n\nالمادة :\nMGT-301\n\nالتحضير :\nيومياً , آخر الكلاس\n\nطريقة الشرح :\nمملة يجلس عالكرسي , وفاتح سلايدات ( مايرضى يرسلها للطلاب ) والمادة سوالف\n\nالكويزات :\n5 كويزات , من كل ماهب ودب , اختيارات , صح وخطأ , Essay\nمايحذف أسوأ كويز , ولا يأجل شيء , وكل بداية كلاس يكتب عالسبورة وش الملاحظات عن كلاس اليوم وش بيسوي + اقرب اختبار وأقرب هومورك <<\n\nالمياجر:\nصعبه , يلعب بالأسئلة , تقراه تحسبك تعرفه , وأثره مغير كلمة لعب بالسؤال\n-- من كل ماهب ودب , اختيارات , صح وخطأ , Essay --\n\nالفاينلات :\nمثل المياجر بالضبط\n\nالقريد النهائي:\nأعطيه D\n\nالصوت:\nلازم تجلس قدام شوي عشان تسمع له\n\nإضافات :\nترتيبه الثاني على دفعته بـ ( ثالث ثانوي ) على المملكة كلها ماشاء الله 🤪\nترتيبه الثاني على دفعته بـ ( جامعة البترول ) في تخرجه , قبل 40 سنة تقريباً ماشاء الله 🤪\nكل يوم يجيب قصص عن عياله أو يوم صار مسؤول بالجامعة , واستقال ورجع للتدرس\nخريج البترول , بأدفرررر أيام لها , ينتج عنها دكتور ( كل درجة تسويها وكل همس محسوب عليك ) … لا يحذف أسوأ كويز , ولا يحذف غياب , ولا يعطي أب قريد ولا يسوي لك شيء", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1163377-mgt301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulrahim-a-al-meer/98462/17", "user": "i_Bo_Da7m", "ts": 1358073487000, "tid": 98462, "pn": 17}}]}', 1358073487000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s.a.l.m.a.n-mgt301', 'stk-s.a.l.m.a.n', 'MGT 301', 'doc', '{"docs": [{"id": "stk-dr-f98473", "n": "Dr. Razali Bin Mat Zin", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده MGT301\n\nالتحضير :\nيحضر يوميا ويهتم بالتحضير\n\nطريقة الشرح :\nسلايدات , ويحب يناقش الطلاب و يشركهم بالشرح + يجيب احيانا cases من ارض الواقع\n\nالكويزات :\nما كان فيه كويزات\n\nالمياجر:\nكان فيه 3 مياجر , كان بيقسمها 20% لكل واحد , ثم بعد ميجر 2 قال الثالث بخليه زي اكسترا وآخذ لكم احسن 2\nطبعا كانت صح وخطا و اختيارات\n\nالفاينلات :\nصح وخطا و اختيارات\n\nالقريد النهائي:\nالدكتور جيد , اعطيه +B\n\nالصوت:\nواضح\n\nإضافات :\nالدكتور طيب ومتفهم , تخصصه اصلا HR\nلو كنت بنزل كورس اليكتف MGT بنزل معاه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1058113-mgt301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-razali-bin-mat-zin/98473/11", "user": "S.a.l.m.a.n", "ts": 1340284423000, "tid": 98473, "pn": 11}}]}', 1340284423000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8581-mgt301', 'stk-user8581', 'MGT 301', 'doc', '{"docs": [{"id": "stk-dr-f98473", "n": "Dr. Razali Bin Mat Zin", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT 301 - Term 152\n\nالتحضير\n: بداية الكلاس ينادي بالأسماء وبعدها يوزع ورقة التحضير ويخلي الطلاب يوقعون + إنتبه تحضر أحد . أعتقد إنه يحذف غياب واحد من الكل .\n\nطريقة الشرح\n: من السلايدات وييبدي في شرح الموضوع بأسئلة او يعطي امثلة من الواقع … الصراحة اول 4 أسابيع كان الكلاس ممل جداً لكن مع الوقت الشباب بدأوا يتفاعلون معاه ويشاركون ونفس الوقت هو قام يأخذ ويعطي معانا .\n\nالكويزات : يعطيك كويزين سهلين ويحذف الأسوء منهم و عليهم 5 درجات\n\nالمياجر:\nبالنسبة لي اشوفها صعبة خاصة إذا كنت منزل الكورس لأنك سمعت إن الكورس سهل … لاتذاكر بس من السلايدات حاول تذاكر من الكتاب\n\nوركز على :\n\n- تعريفات النظريات والقوانين + اسماء الأشخاص الي طرحوا هذي النظريات .\n- tables و diagrams\n- أحفظ التعريفات لأنه راح يعيك اسئلة اكمل فراغ .\n- أفهم النظريات وبعض المصطلحات لأنه ما يعطي اسئلة مباشرة مثلا يعطيك موقف ويسألك اي نظرية استخدمها المدير مع الموظف .\n\nالفاينل\n: كان صعب : تقريبا 40 فقرة صح وخطأ و 10 فقرات اكمل فراغ و 10 أكمل فراغ وفي النهاية سؤال ريتين والوقت ساعة بس !!.\n\nالقريد النهائي:\nالرجال حبيب وطيب ومتعاون لكن بالنسبة لي ماعجبتني طريقته في المياجر والفاينل صحيح طلعت معاه بـ b+ لكن متأكد لو كنت مع دكتور ثاني راح أخذ قريد اعلى و بنفس المجهود يمكن العيب مني لأني مب متقبل الكورس لأنه مب طالب mgt\n\nتوزيع للقريدات مب ستنادرد لو سألته في بداية السمستر او حتى في الفاينل راح يقولك بيكون ستنادرد لكن في الواقع مب ستنادرد انا مجموعي في السبعينات و خذت b+\n\nالصوت:\nواضح … والاكسنت جيد + هو ماليزي .\n\nإضافات :\n\n- في بروجكت بسيط عليه تقريبا 15 درجة ( 5 للبرزنتيشن + 10 على الريبورت ) : في بداية السمستر يطلب منكم تسو قروب من 5 أو 6 طلاب وبعدها راح يعطيكم مقالة تقريبا من 4 صفحات عن موضوع معين مثلا Google او BP وفي نهاية المقال تقريبا 6 اسئلة المطلوب منكم :\n1- ريبورت تجاوبون هذي الاسئلة ( اغلب الاسئلة اجابتها موجودة في المقال لكن نصيحة بعد ماتجاوب على الاسئلة حاول تبحث في النت عن مصادر ثانية وتضيفها لإجابتك وهو يفضل هذا الشيئ + اذكر المصادر نهاية الريبورت وسو لها in text citation )\n2 - برزنتيشن تقريبا الاسبوع 13 عن الريبورت .\n\n- فيه 5 درجات على المشاركة فحاول تكون في الصف الأول ودايما تشارك معاه عشان يحفظك ويعطيك فل مارك في المشاركة وإذا ماكنت تشارك ماراح يعطيك فل مارك .\n\n- هو غير مرن من ناحية الهوموركات أو مواعيد تسليم البروجكت فحاول تسلم كل شي على الوقت .\n- فيه بعض الشباتر حذفها لأنها موجودة في كورسات ثانية + الماتيريال لميجر 1 تقريبا كان 4 شباتر ونفس الشي في ميجر 2 اما الفاينل راح يسئلكم كم شابتر تبون فقولوا له 4 شباتر لأن قلنا له 5 شباتر وما رضى إنه يخليهم 4 .\n\n- ما يعتمد على TB ومثل ماسمعت إن كلية الإدارة نبهت الدكاترة إنهم يستغنون عن الـ tb في المياجر والكويزات من السمستر الجاي والعهدة على الراوي .\n\nهذا رابط (ارسله واحد من الشباب الله يجزاه خير )\nفيه :\n\nMGT 301 _ Term 152 - Razali.Matizn\n\n- ميجر 1 & 2 لـ Term 152\n- الكويز الأول والثاني\n- السلاباس\n\nهذي السلايدات\nMGT301_SLIDES\n\nهذا الـ tb\nmgt 301 - tb 11th edition", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1450139-mgt301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-razali-bin-mat-zin/98473/19", "user": "user8581", "ts": 1464025663000, "tid": 98473, "pn": 19}}]}', 1464025663000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_taki-mgt301', 'stk-abu_taki', 'MGT 301', 'doc', '{"docs": [{"id": "stk-dr-f98473", "n": "Dr. Razali Bin Mat Zin", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT 301 - 162\n\nبنود التقييم :\n\nالتحضير :\n\nورقة توقع عليها … متسامح مع التأخير … أحياناً يمسك الورقة وينادي الأسماء عشان يتأكد انه محد حضر خويه\n\nطريقة الشرح :\nيستخدم سلايدات لكنه مو من النوع اللي يقراها فقط… شرحه جيد جداً لكنه يصبح ممل بعض الأحيان حسب طبيعة الدرس\n\nالكويزات :\nكويزين ويحسب لك افضل كويز منهم … الكويزات سهلة الى متوسطة وتكون عن شابتر واحد\n\nالمياجر:\nالميجر الأول كان قنبلة موقوتة … الافرج كان 10 من 20 تقريبا … وكان 15 درجة منه MCQ و 5 درجات Written بين اكمل الفراغ واجابات قصيرة\nالميجر الثاني كان اقل صعوبة نوعاً ما من الميجر الأول لكنه ما يعتبر سهل ابداً… طبعا في الميجر الثاني قلل نسبة الـ written وصار 17.5 ملتبل شويس و 2.5 Written …\nافرج الميجر الثاني كان 12 من 20\n\nالفاينلات :\nالفاينل كان متوسط الصعوبة … بمستوى الميجر الثاني تقريبا\n\nالقريد النهائي:\nB\n\nالصوت:\nجيد\n\nإضافات :\n\n- المياجر والفاينل كل اختبار تختبر في 4 شباتر … اعتقد الفاينل كان المفترض يكون في شباتر اكثر لكن بسبب التقديم خلاه في 4 شباتر فقط\n- اختباراته تركز بشكل كبير على الفهم اكثر من الحفظ … لانه معظم الأحيان يحول المفاهيم الى Cases ويسألك عنها في الاختبار … فاحرص انك تذاكر قبل الاختبار بـ 3-4 أيام على الأقل وتفهم الشباتر كويس\n- أحياناً يجيب أشياء غير متوقعة في الأختبار فحاول تغطي كل شي قد ما تقدر … مثلا ممكن يسألك عن اسم صاحب النظرية او اسم كتاب معين\n- في السي لبس المادة ستاندرد … لكنه بعد الميجر الثاني قال انه يفكر جدياً يخليها أفرج… بالنهاية ما خلاها أفرج لكن اللي سواه أنه خلا الـ A+ من 90 و A من 85 … الخ\nيعني تقدر تقول خلاها ستاندرد ورفع كل واحد قريد\n- الدكتور متوسط … لا هو كارثي ولا هو ممتاز … اختيارك له من عدمه يعتمد ع الدكاترة الآخرين المتوفرين لتدريس المادة ( اقصد MGT 301 ) … بس بشكل عام القريد معاه مو سهل … ما شفت قريدات باقي الطلاب بس اعتقد الغالبية عنده بين C و C+ وقليل اللي جابوا B+ وفوق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474672-mgt301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-razali-bin-mat-zin/98473/20", "user": "Abu_Taki", "ts": 1496798577000, "tid": 98473, "pn": 20}}]}', 1496798577000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9840-mgt301', 'stk-user9840', 'MGT 301', 'doc', '{"docs": [{"id": "stk-dr-f98473", "n": "Dr. Razali Bin Mat Zin", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT 301 Term 162\n\nبنود التقييم :\n\nالتحضير : يمرر ورقة وتوقع وبعدها ينادي بالاسماء لذلك لاتلعب بذيلك\n\nطريقة الشرح : ممتعة الصراحة والرجال فاهم وفات المنجمنت فت فراح يعطيك كثير امثلة من واقع الحياة خصوصا من بلده ماليزيا .\nالكويزات : كويزين عليهم 5 ياخذ الافضل\nالمياجر: حررررررررريقة ،ينافس ديبارتمنت الفيزكس\nالفاينلات : مقبول لانه حب ينزل الافرج بسبب اللي عمله في المياجر\nالقريد النهائي: B\nالصوت: كويس\nإضافات :\nفي الميجر الثاني ماحجز قاعة الاختبارات وجلسنا في القاعة وبس ، بعد بداية الاختبار بربع ساعة طلع في دكتور آخر حاجز القاعة وطشرنا على قاعتين وصارت فوضة وغش ، ولا جانا زعلان يقول ليه تغشون … بالنسبة للقريدات ستاندرد لكنه نزل السكيل على خمس درجات يعني A+ من 90", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1475980-mgt301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-razali-bin-mat-zin/98473/21", "user": "user9840", "ts": 1499307633000, "tid": 98473, "pn": 21}}]}', 1499307633000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2526-mgt301', 'stk-user2526', 'MGT 301', 'doc', '{"docs": [{"id": "stk-dr-f98478", "n": "Dr. Mohamed Osman Shereif Mahdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "mgt 301-111\n\nالتحضير :\nنهاية المحاضرة و حتى اذا جيت متأخر راح يحضرك مع انه في اول محاضرة يقول لا تتأخرون بس الوضع عنده طبيعي مع التأخير\n\nطريقة الشرح :\nيقرأ من السلايدات و كل يوم يشرح شابتر كامل و بعد كل 3-4 كلاسات تكون في محاضرة توتوريال يعني يجي و يجيب الاسئلة الي في السمري حق الشابتر و يسأل الطلاب و الطلاب يجاوبون و الكتب مفتوحة\n\nالكويزات :\nيجيب عدد و صح و خطأ و ملتبل شويس\nاسألته من التي بي بس يغير بعض الاسماء في بعض الاسئلة مثل يكون السؤال عن شركت مايكروسوفت يغير كلمة مايكروسوفت و يحط الجامعة\n\nالمياجر:\nنفس الكوزات\n\nالفاينلات :\nنفس الكوزات بس الاسئلة ما فيها عدد لأنك بتستخدم ببل شيت\n\nالقريد النهائي:\nB\n\nالصوت:\nواضح\n\nإضافات :\nالدكتور ما شاء الله عليه يحفظ يعني على نهاية السمستر بيكون عارف مين اللي يشارك و مين الي نايم و مين الي دايم يجي متأخر\n\nالمادة عنده ستاندرد مو افرج\n\nعلشان تطلع ب A+ يحتاج انك تفهم السلايدات حقينه مع حفظ و فهم التي بي\n\nبالنسبة للدرجات اخر شي رفع كل الطلاب قريدين يعني الي ماخذ B اعطاه A\n\nالدكتور هذا صارم الى ابعد درجة مثلا في مواعيد الكوزيز و المياجر و البروجيكت\n\nفي نهاية السمستر يعطي بروجيكت عليه 5 او 10 ناسي المهم و خلي 7 طلاب يشتغلون عليه و يعطونه ريبورت مكون من ورقتين و بعدين في برسينيشن", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p967330-mgt301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohamed-osman-shereif-mahdi/98478/8", "user": "user2526", "ts": 1326541165000, "tid": 98478, "pn": 8}}]}', 1326541165000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hisham.s-mgt301', 'stk-hisham.s', 'MGT 301', 'doc', '{"docs": [{"id": "stk-dr-f118715", "n": "Dr. Eid S. Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT301 TERM 132\n\nالتحضير :\nكل يوم يحضر\n\nطريقة الشرح :\nممتاز اذا انت متابع معه\nجمع بين المعرفة الأكاديمية والخبرة العملية .\nالكويزات :\nessay questions\nعدد، عرف ، اشرح واحيانا اختيارات\nالمياجر:\nessay questions\nعدد، عرف ، اشرح واحيانا اختيارات\nالفاينلات :\nessay questions\nعدد، عرف ، اشرح واحيانا اختيارات\nالتقييم النهائي:\nA\n\nالصوت:\nواضح تماماً\n\nإضافات :\nدكتور مخضرم ومن الأساتذة الذين أكن لهم كثير من التقدير والإحترام.\nمن امتع الكورسات اللي اخذتها معه بغض النظر عن القريد.\nلازم تركز معه وتقرأ الكتاب وتفهمه\nالمادة طويلة جدا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1448932-mgt301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-eid-s-al-shammari/118715/6", "user": "hisham.s", "ts": 1463194137000, "tid": 118715, "pn": 6}}]}', 1463194137000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_182-mgt301', 'stk-_182', 'MGT 301', 'doc', '{"docs": [{"id": "stk-dr-f118715", "n": "Dr. Eid S. Al-Shammari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT301-182\n\nمرفق مع الرسالة فهرس المادة\nالتحضير: بداية المحاضرة، نادرًا ما يحضّر بالأخير\nطريقة الشرح: يعتمد على السلايدات، يقرأ منها شوي ثم يبدأ يشرح ويضرب أمثلة من عنده\nالكويزات: ما فيه\nالمياجر: مياجر الدكتور تغطّي 4 فصول، هذا الترم أسئلة الاختبار كانت فقط خيارات MCQs، نسيت كم سؤال بس أظن 40 لكل ميجر، أغلب الأسئلة واضحة ومباشرة، ممكن سؤال أو اثنين في كل اختبار بتحتار فيه\nالفاينلات: 5 فصول وبرضو MCQs، عدد الأسئلة 55 (مو متأكد من الرقم)، أغلب الأسئلة مباشرة، بعض الأسئلة ممكن تتحيّر فيها لأن أكثر من جواب تحس أنه صحيح\nالقريد النهائي: +A\nالصوت: واضح، واللغة الإنجليزية ممتازة\nإضافات:\n\n- اختبارات هذه المادة غير موحدة، اختبارات الدكتور ذاكرها من السلايدات بتضمن معظم الدرجة، لكن هذا لا يعني أنه مرح بيجيب سؤالين ثلاثة من الكتاب\n- أي شيء ذكرته في نقطة الكويزّات، المياجر والفاينلات قابل للتغيير من ترم لآخر\n- نصيحة: انتبه تعتمد على التيست بانك\n- الدكتور يعطي أساينمنت عليه %20، الأساينمنت مرفق مع الرد، شغلنا كان شبه تعبان وعطانا %17، وما أشوف أننا استحقّيناها (موعد التسليم كان الصباح واشتغلنا ليلتها)\n- متجاوب مع الإيميلات، وبالساعات المكتبية أحيان يكون موجود وأحيان لا، تأكد قبل ما تروح\n- مرن في التحضير، ما أدري هل سجّل أحد تأخير خلال الترم أو لا، وإذا عندك ظرف وتبي تغيب عطه خبر قبل وبيعذرك، الدكتور جدًّا متفهم وحبيب\n- خبرة الدكتور في المجال أكبر من أنّي أقيّمها، أؤكّد لك أنك راح تستفيد منه الشيء الكثير، يحب النقاش فلو عندك أسئلة لا تتردّد\n- خفيف دم، في كل محاضرة يرمي نكتة، يضحّك لا خرج عن النص باللهجة العاميّة\n- آفرج الكورس كان 75.1، أنا جبت 86.9 وعطاني A\n- بإمكانك تجيب قريد عالي مع الدكتور، بس استعد زين للمياجر وحط جهد معقول في الأساينمنت، وأمورك طيبة إن شاء الله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509717-mgt301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-eid-s-al-shammari/118715/8", "user": "_182", "ts": 1557841503000, "tid": 118715, "pn": 8}}]}', 1557841503000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sadguts-mgt301', 'stk-sadguts', 'MGT 301', 'doc', '{"docs": [{"id": "stk-dr-f180466", "n": "Dr. Omar Al-Zamel", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MGT301 - 202\nماكان يحضر بالاونلاين وايجابيته يخلص الكلاسات ب 30-45 د بالكثير\nشرحه كويس ويعطي امثلة حلوة بس المادة كانت مملة بالنسبة لي لان يغلب عليها الحفظ الا اخر التشابترات حقت الHR (تشابتر 10 اظن)\nوتشابتر 13 حق الهيومن بيهيفير كانت رهيبة\n\nاعطانا هوموركين وبروجكت وكان تصحيحه كويس الاغلب اخذ درجات حلوة مع انه ف البروجكت نقص البعض (للامانة ماوضح المطلوب بشكل كويس) لكن مجملا القروب بروجكت مو صعب\n\nالميد تيرم كان متوسط والفاينل كان اصعب بشوي لكن مجملا معقولة والدكتور كويس جدا انصح فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531526-mgt301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/omar-al-zamel/180466/2", "user": "SadGuts", "ts": 1630067483000, "tid": 180466, "pn": 2}}]}', 1630067483000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
